class Money:
    def __init__(self, cents):
        self.cents = cents

    def __add__(self, o):
        return Money(self.cents + o.cents)

    def __eq__(self, o):
        return isinstance(o, Money) and self.cents == o.cents

    def __repr__(self):
        return f'Money({self.cents})'

    def __str__(self):
        return f'${self.cents / 100:,.2f}'

    def split(self, n):
        share = self.cents // n
        return [Money(share) for _ in range(n)]

import unittest

from money import Money


class T(unittest.TestCase):
    def test_add(self):
        self.assertEqual(Money(150) + Money(275), Money(425))

    def test_str(self):
        self.assertEqual(str(Money(5)), '$0.05')
        self.assertEqual(str(Money(123456)), '$1,234.56')
        self.assertEqual(str(Money(-250)), '-$2.50')

    def test_split(self):
        self.assertEqual(Money(100).split(3), [Money(34), Money(33), Money(33)])
        self.assertEqual(sum((m.cents for m in Money(7).split(4))), 7)


if __name__ == '__main__':
